{"command":"python3 -c "
import csv
with open('outputs/t02_eurostat_raw.csv', 'r', newline='') as f:
    reader = csv.reader(f)
    header = next(reader)
    rows = list(reader)

    # Check each row has exactly 7 fields
    bad_rows = []
    for i, row in enumerate(rows):
        if len(row) != 7:
            bad_rows.append((i, len(row), row))

    if bad_rows:
        print(f'Found {len(bad_rows)} rows with incorrect field count')
        for r in bad_rows[:5]:
            print(r)
    else:
        print('All rows have exactly 7 fields')
